def find_middle(s):
    if not isinstance(s, str):
        return -1

    digits = [int(char) for char in s if char.isdigit()]

    if not digits:
        return -1

    product = 1
    for digit in digits:
        product *= digit

    product_str = str(product)

    if len(product_str) % 2 == 0:
        middle = product_str[len(product_str) // 2 - 1:len(product_str) // 2 + 1]
        if middle[0] == '0':
            return int(middle[1])
        return int(middle)
    else:
        middle = product_str[len(product_str) // 2]
        return int(middle)

# Example usage:
